#include <iostream>
#include <memory>
using namespace std;

int main() {
    shared_ptr<int> a = make_shared<int>(100);
    cout << "count: " << a.use_count() << endl;

    {
        shared_ptr<int> b = a;
        cout << "count: " << a.use_count() << endl;
    }

    cout << "count: " << a.use_count() << endl;
    return 0;
}
